import{_ as a,a as i}from"./chunks/2026-08-27-r2-diagnostic-review.CA4P3-yJ.js";import{_ as n,C as o,o as s,c as r,E as c,a2 as l}from"./chunks/framework.Cm6XCzck.js";const w=JSON.parse('{"title":"From ‘Evidence Must Not Be Cross-Booked’ to Dynamic Diagnosis: How CodeFlowMu V2.0.4 Turned a Research Finding into an Engineering Capability","description":"","frontmatter":{"title":"From ‘Evidence Must Not Be Cross-Booked’ to Dynamic Diagnosis: How CodeFlowMu V2.0.4 Turned a Research Finding into an Engineering Capability","date":"2026-08-27","column":"open-source-engineering","category":"daily","article_type":"engineering-case-study","edition":"research-center","research_question":"How can a research finding about evidence ownership become a read-only, lifecycle-aware diagnostic through implementation, real-task calibration, and production validation?","summary":"R2 began with ten historical REPORT records and one finding: lifecycle location does not prove evidence ownership. That principle entered CodeFlowMu, was calibrated against real task data during development, and became a dynamic evidence-association diagnostic in the formally released V2.0.4.","sources":"/en/research/evidence/2026-08-27-r2-v204-evidence-association","project_relevance":"first-party-research","item_id":"RSEM-20260827-02","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-27-review-status-evidence-association-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/engineering/2026-08-27-review-status-evidence-association.md","filePath":"en/engineering/2026-08-27-review-status-evidence-association.md","lastUpdated":1787899652000}'),d={name:"en/engineering/2026-08-27-review-status-evidence-association.md"};function p(h,e,u,m,g,b){const t=o("ArticleCover");return s(),r("div",null,[c(t,{image:"/assets/covers/daily-2026-08-27-review-status-evidence-association-cover.png",kicker:"Open-Source Engineering · Engineering Research",title:"From ‘Evidence Must Not Be Cross-Booked’ to Dynamic Diagnosis: How CodeFlowMu V2.0.4 Turned a Research Finding into an Engineering Capability",summary:"This capability began as an evidence-ownership research question, moved through implementation and real-task calibration, and became a lifecycle-aware diagnostic in the formally released V2.0.4.",version:"RSEM-20260827-02",status:"Engineering Research · 2026-08-27",languageHref:"/zh/engineering/2026-08-27-review-status-evidence-association",languageLabel:"中文"}),e[0]||(e[0]=l(`<h1 id="from-evidence-must-not-be-cross-booked-to-dynamic-diagnosis-how-codeflowmu-v2-0-4-turned-a-research-finding-into-an-engineering-capability" tabindex="-1">From “Evidence Must Not Be Cross-Booked” to Dynamic Diagnosis: How CodeFlowMu V2.0.4 Turned a Research Finding into an Engineering Capability <a class="header-anchor" href="#from-evidence-must-not-be-cross-booked-to-dynamic-diagnosis-how-codeflowmu-v2-0-4-turned-a-research-finding-into-an-engineering-capability" aria-label="Permalink to &quot;From “Evidence Must Not Be Cross-Booked” to Dynamic Diagnosis: How CodeFlowMu V2.0.4 Turned a Research Finding into an Engineering Capability&quot;">​</a></h1><p>R2 began with a small question: <strong>if a task is already in <code>review</code>, can the system safely assume that its REPORT, execution record, and REVIEW all belong to the same accountability chain?</strong></p><p>We checked ten reports from one fixed historical slice. Four linked directly by explicit task key. Four lacked the action-side task key. Two assigned the same report to different tasks in two sources.</p><p>The <code>4 / 4 / 2</code> split was never a defect rate. It exposed a narrower principle:</p><blockquote><p><strong>Lifecycle location tells us where a task is. It does not prove who owns each piece of evidence around it.</strong></p></blockquote><p>The valuable part came next. We turned that principle into a read-only diagnostic, calibrated its semantics against real task data during development, completed the engineering work, and shipped the capability in CodeFlowMu V2.0.4.</p><p>The path is therefore:</p><p><strong>research finding → engineering contract → real-task calibration → semantic convergence → formal release → live validation</strong>.</p><h2 id="_1-the-research-origin-relationships-must-come-from-explicit-facts" tabindex="-1">1. The research origin: relationships must come from explicit facts <a class="header-anchor" href="#_1-the-research-origin-relationships-must-come-from-explicit-facts" aria-label="Permalink to &quot;1. The research origin: relationships must come from explicit facts&quot;">​</a></h2><p>The historical check used only explicit fields: the task key attached to a REPORT write and the task key recorded for the same REPORT in the report ledger.</p><table tabindex="0"><thead><tr><th>Two-source relation</th><th>Output</th><th>What the reader must not do</th></tr></thead><tbody><tr><td>both task keys exist and match</td><td><code>linked</code></td><td>infer nothing extra</td></tr><tr><td>one side lacks the task key</td><td><code>missing</code></td><td>infer from filename, time, or role</td></tr><tr><td>both exist and disagree</td><td><code>conflict</code></td><td>choose the more convenient source</td></tr></tbody></table><p>The public fixture yields <code>linked = 4</code>, <code>missing = 4</code>, and <code>conflict = 2</code>.</p><p>The point is not the count. The point is that uncertainty remains visible rather than being cosmetically repaired.</p><p>That research result led to a more explicit evidence graph:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TASK / revision</span></span>
<span class="line"><span>→ attempt</span></span>
<span class="line"><span>→ lease</span></span>
<span class="line"><span>→ execution</span></span>
<span class="line"><span>→ action evidence</span></span>
<span class="line"><span>→ REPORT</span></span>
<span class="line"><span>→ REVIEW / EVAL</span></span>
<span class="line"><span>→ business decision</span></span></code></pre></div><p>Each edge must answer one narrow question: <strong>why are these records allowed to be connected?</strong></p><h2 id="_2-the-engineering-translation-a-diagnostic-not-another-state-machine" tabindex="-1">2. The engineering translation: a diagnostic, not another state machine <a class="header-anchor" href="#_2-the-engineering-translation-a-diagnostic-not-another-state-machine" aria-label="Permalink to &quot;2. The engineering translation: a diagnostic, not another state machine&quot;">​</a></h2><p>R2 was implemented as a separate, read-only evidence-association diagnostic.</p><p>It asks whether:</p><ul><li>the current task revision links to a specific attempt;</li><li>the attempt links to a lease;</li><li>the attempt links to an execution;</li><li>the execution links to terminal action evidence;</li><li>the REPORT links to the current task;</li><li>the REPORT links to the formal REVIEW;</li><li>an EVAL, when present, has an explicit relationship to REVIEW.</li></ul><p>The diagnostic reads formal sources and produces derived snapshots. It does not rewrite TASK, REPORT, REVIEW, attempt, lease, or lifecycle state.</p><p>That is why the feature is better understood as an X-ray than a judge.</p><h2 id="_3-an-independent-crewai-reference-a-process-is-not-one-completion-event" tabindex="-1">3. An independent CrewAI reference: a process is not one completion event <a class="header-anchor" href="#_3-an-independent-crewai-reference-a-process-is-not-one-completion-event" aria-label="Permalink to &quot;3. An independent CrewAI reference: a process is not one completion event&quot;">​</a></h2><p>This problem is not unique to our task ledger. A recent CrewAI change provides a useful independent engineering reference.</p><p>In <a href="https://github.com/crewAIInc/crewAI/pull/7115" target="_blank" rel="noreferrer">CrewAI PR #7115</a>, João Moura did <strong>not</strong> move the existing deployment-creation event to the success point. The change deliberately keeps <code>Create Crew Deployment</code> as the pre-call <strong>creation-attempt</strong> event and adds a separate post-success <code>Crew Deployment Created</code> event that can carry the UUID returned only after creation succeeds. The PR was merged on August 27, 2026.</p><p>That separation matters because an attempt and a confirmed success are different facts. Moving the original event would silently change the historical meaning of the metric from attempts to successes. PR #7115 explicitly avoids that semantic substitution.</p><p>The PR body also reports that <code>create_deployment</code> was reading 76,015 historical events with zero UUID-bearing records at that point. That figure is source-reported by the CrewAI authors; we did not independently reproduce it and do not present it as our own measurement.</p><p>The same author’s <a href="https://github.com/crewAIInc/crewAI/pull/7118" target="_blank" rel="noreferrer">CrewAI PR #7118</a> remains open. It proposes a separate ungated <code>Crew Completed</code> terminal event carrying <code>outcome</code> and <code>duration_ms</code>, joinable to the existing crew-start/creation records. Because the PR is still open, this article treats it as directional public material, not as a shipped CrewAI capability.</p><p>The relationship to R2 is deliberately narrow:</p><blockquote><p><strong>Each stage needs its own evidence. A creation request is not a confirmed creation; an execution attempt is not a submitted REPORT; a submitted REPORT is not an accepted REVIEW.</strong></p></blockquote><p>CrewAI is not an implementation source for CodeFlowMu, and #7115/#7118 do not prove that R2 is correct. They are independent public references showing another agent-engineering project separating process events, terminal events, and joinable identifiers rather than collapsing them into one generic completion fact.</p><h2 id="_4-real-task-calibration-during-development" tabindex="-1">4. Real-task calibration during development <a class="header-anchor" href="#_4-real-task-calibration-during-development" aria-label="Permalink to &quot;4. Real-task calibration during development&quot;">​</a></h2><p>Once the theory entered code, the important work was not to display more edges as quickly as possible. It was to determine which values were actually comparable and which relations were truly required at a given stage.</p><p>Real task <code>TASK-20260827-024</code> helped calibrate several rules during development.</p><p>First, values from different revision domains must not be compared as though they were the same business revision. A current-file digest can support caching and change detection without becoming a lifecycle revision.</p><p>Second, collaboration context must not become ownership. Parent-task references and linked-task metadata are useful context, but REPORT ownership requires direct stable keys.</p><p>Third, “not yet materialized in one store” is not the same as “execution absent.” When an attempt already carries a formal <code>session_id</code> and runtime receipts/events identify the execution, the diagnostic can project that execution read-only.</p><p>Fourth, when progress and final reports coexist, the current formal REPORT needs an explicit anchor. V2.0.4 uses <code>current_final_report_id</code> for that purpose.</p><p>These were normal engineering-calibration decisions for a new diagnostic capability. They narrowed the meaning of revision, ownership, execution, and current REPORT until the implementation matched the intended evidence contract.</p><h2 id="_5-v2-0-4-formal-release-the-same-qa-task-changes-diagnosis-from-active-to-review" tabindex="-1">5. V2.0.4 formal release: the same QA task changes diagnosis from <code>active</code> to <code>review</code> <a class="header-anchor" href="#_5-v2-0-4-formal-release-the-same-qa-task-changes-diagnosis-from-active-to-review" aria-label="Permalink to &quot;5. V2.0.4 formal release: the same QA task changes diagnosis from \`active\` to \`review\`&quot;">​</a></h2><p>After the feature was complete and V2.0.4 was formally released, we captured two local UI views of the same task:</p><p><code>TASK-20260827-030-PM-to-QA</code></p><p>The first screenshot shows the task in <code>active</code>. The second shows the same task in <code>review</code>.</p><p>The two raw UI screenshots below are first-party page evidence for the <strong>same task</strong>, not static mockups. The first shows <code>active</code>; the second shows that task after it reaches <code>review</code>. Their value is that the diagnostic recomputes evidence relationships as the formal lifecycle facts change.</p><h3 id="stage-a-active-—-no-report-yet-means-not-applicable" tabindex="-1">Stage A: <code>active</code> — no REPORT yet means not applicable <a class="header-anchor" href="#stage-a-active-—-no-report-yet-means-not-applicable" aria-label="Permalink to &quot;Stage A: \`active\` — no REPORT yet means not applicable&quot;">​</a></h3><p>The visible summary is:</p><ul><li>linked: 4</li><li>missing: 0</li><li>conflict: 0</li><li>observer-only: 0</li></ul><p>The visible linked edges include:</p><ul><li>task revision → attempt</li><li>attempt → lease</li><li>attempt → execution</li><li>execution → action evidence</li></ul><p>No formal REPORT exists yet, so the REPORT edges are correctly <strong>not applicable</strong>, not missing:</p><ul><li><code>REPORT → Task</code>: <code>not_applicable</code></li><li><code>REPORT → REVIEW</code>: <code>not_applicable</code></li></ul><p>The crucial fact is <code>missing=0 / conflict=0</code>. At this stage, no REPORT is expected, so reporting a missing REPORT would itself be inaccurate.</p><p><a href="/joinwell52/assets/figures/2026-08-27-r2-diagnostic-active.png"><img src="`+a+'" alt="Evidence-association diagnostic for the same QA task in active: four execution-chain relations are linked and REPORT relations are not applicable at this stage"></a></p><p><em>Figure 1. The same QA task is still <code>active</code>. Its revision, attempt, lease, execution, and action evidence can be connected. A formal REPORT has not yet been produced, so REPORT relations are <strong>not applicable</strong>, rather than missing.</em></p><h3 id="stage-b-review-—-report-relationships-become-linked-when-the-evidence-exists" tabindex="-1">Stage B: <code>review</code> — REPORT relationships become linked when the evidence exists <a class="header-anchor" href="#stage-b-review-—-report-relationships-become-linked-when-the-evidence-exists" aria-label="Permalink to &quot;Stage B: `review` — REPORT relationships become linked when the evidence exists&quot;">​</a></h3><p>After the same task enters <code>review</code>, the diagnostic recomputes the graph:</p><ul><li>attempt → lease: linked</li><li>attempt → execution: linked</li><li>execution → action evidence: linked</li><li>REPORT → Task: linked</li><li>REPORT → REVIEW: linked</li></ul><p>The remaining EVAL edge is:</p><ul><li><code>EVAL → REVIEW</code>: <code>not_applicable</code> / <code>eval_not_present</code></li></ul><p>That is also the correct result. This is a <strong>QA task</strong>. In the current workflow, EVAL belongs to the PM path, so this QA task is not expected to carry an EVAL report.</p><p><a href="/joinwell52/assets/figures/2026-08-27-r2-diagnostic-review.png"><img src="'+i+'" alt="Evidence-association diagnostic for the same QA task in review: REPORT to Task and REPORT to REVIEW are linked, while EVAL to REVIEW remains not applicable"></a></p><p><em>Figure 2. Once the same task reaches <code>review</code>, the diagnostic rereads the formal facts. REPORT → Task and REPORT → REVIEW move from not applicable to linked; EVAL remains not applicable because this QA path does not require one.</em></p><p>The pair therefore demonstrates a specific production capability:</p><blockquote><p><strong>Evidence requirements change with lifecycle stage and role, and the diagnostic changes with the formal facts instead of forcing every edge into linked or missing.</strong></p></blockquote><h2 id="_6-not-applicable-is-a-first-class-semantic-state" tabindex="-1">6. <code>not_applicable</code> is a first-class semantic state <a class="header-anchor" href="#_6-not-applicable-is-a-first-class-semantic-state" aria-label="Permalink to &quot;6. `not_applicable` is a first-class semantic state&quot;">​</a></h2><p>A useful agent-runtime diagnostic needs more than healthy/unhealthy.</p><p>Evidence requirements are stage- and role-dependent:</p><ul><li>while a task is active, a final REPORT may not yet be required;</li><li>in review, REPORT and REVIEW relationships become relevant;</li><li>a QA task may legitimately have no PM-path EVAL.</li></ul><p>The diagnostic therefore distinguishes at least:</p><ul><li><code>linked</code>: explicit stable keys establish the relation;</li><li><code>missing</code>: the current stage requires evidence that was not found;</li><li><code>conflict</code>: comparable explicit facts disagree;</li><li><code>not_applicable</code>: this stage or role does not require the relation;</li><li><code>observer_only</code>: an observation exists but carries no lifecycle authority.</li></ul><p>This is not UI decoration. It is part of the semantic contract.</p><h2 id="_7-the-most-important-boundary-in-the-ui" tabindex="-1">7. The most important boundary in the UI <a class="header-anchor" href="#_7-the-most-important-boundary-in-the-ui" aria-label="Permalink to &quot;7. The most important boundary in the UI&quot;">​</a></h2><p>The V2.0.4 task detail states:</p><blockquote><p><strong>This conclusion describes evidence relationships only. It does not mean the task has been delivered or verified successfully.</strong></p></blockquote><p>That sentence prevents evidence association from becoming hidden adjudication.</p><p><code>REPORT → REVIEW = linked</code> establishes only that the current formal REPORT and REVIEW are connected by the relevant stable keys.</p><p>It does not establish that:</p><ul><li>the REPORT is truthful;</li><li>the REVIEW conclusion is correct;</li><li>QA has passed;</li><li>ADMIN accepted delivery;</li><li>the task is eligible for <code>done</code>.</li></ul><p>Evidence association is an observation layer. Delivery and acceptance remain separate decisions.</p><h2 id="_8-two-practical-actions-make-it-an-engineering-tool" tabindex="-1">8. Two practical actions make it an engineering tool <a class="header-anchor" href="#_8-two-practical-actions-make-it-an-engineering-tool" aria-label="Permalink to &quot;8. Two practical actions make it an engineering tool&quot;">​</a></h2><p>The review-stage UI also exposes:</p><ul><li><strong>copy reconciliation summary</strong>;</li><li><strong>recheck evidence association</strong>.</li></ul><p>The first helps operators carry the current relationship state into further review without reconstructing it from logs.</p><p>The second forces the diagnostic to reread current formal facts and recompute the snapshot rather than treating cached output as permanent truth.</p><p>Neither action changes formal lifecycle state.</p><p>That is why V2.0.4 adds more than a task-detail view. It adds an operational evidence-association diagnostic.</p><h2 id="_9-why-this-is-a-genuine-research-to-engineering-case" tabindex="-1">9. Why this is a genuine research-to-engineering case <a class="header-anchor" href="#_9-why-this-is-a-genuine-research-to-engineering-case" aria-label="Permalink to &quot;9. Why this is a genuine research-to-engineering case&quot;">​</a></h2><p>The sequence matters:</p><p><strong>Step 1 — historical research.</strong> Ten reports yielded <code>4 linked / 4 missing / 2 conflict</code> and the finding that lifecycle position is not evidence ownership.</p><p><strong>Step 2 — engineering contract.</strong> TASK, attempt, lease, execution, action, REPORT, REVIEW, and EVAL became explicit relationship edges.</p><p><strong>Step 3 — real-task calibration during development.</strong> We refined which revisions can be compared, which keys establish REPORT ownership, how execution may be projected, and how the current final REPORT is anchored.</p><p><strong>Step 4 — formal V2.0.4 release.</strong> The diagnostic became a shipped product capability.</p><p><strong>Step 5 — live lifecycle validation.</strong> The same QA task moved from <code>active</code> to <code>review</code>: REPORT edges were correctly not applicable before the report existed, became linked when review evidence appeared, and EVAL remained not applicable because this QA path does not require it.</p><p>That is the research value: <strong>the theory survived contact with the real data model, lifecycle, roles, and runtime state required to become a usable product capability.</strong></p><h2 id="_10-public-verification" tabindex="-1">10. Public verification <a class="header-anchor" href="#_10-public-verification" aria-label="Permalink to &quot;10. Public verification&quot;">​</a></h2><p>The complete <a href="/joinwell52/en/research/evidence/2026-08-27-r2-v204-evidence-association">R2 → CodeFlowMu V2.0.4 engineering evidence pack</a> is published separately.</p><p>The historical research artifacts remain public:</p><ul><li><a href="/joinwell52/assets/evidence/2026-08-27-r2-report-association-fixture.json">ten deidentified REPORT association records</a></li><li><a href="/joinwell52/assets/evidence/2026-08-27-r2-association-reader.mjs">public association Reader</a></li><li><a href="/joinwell52/assets/evidence/2026-08-27-r2-association-reader-check.mjs">public check</a></li></ul><p>The V2.0.4 live comparison also has a structured transcript and consistency check:</p><ul><li><a href="/joinwell52/assets/evidence/2026-08-27-r2-v204-dynamic-diagnostic-snapshots.json">active/review dynamic diagnostic snapshots</a></li><li><a href="/joinwell52/assets/evidence/2026-08-27-r2-v204-dynamic-diagnostic-check.mjs">dynamic snapshot consistency check</a></li></ul><p>The two first-party UI screenshots are embedded above. The structured artifacts preserve the stage, visible edges, statuses, and reason codes in machine-checkable form.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>R2 began by asking whether REPORTs could be cross-booked.</p><p>By V2.0.4, the more useful question is:</p><p><strong>Can the runtime keep answering, as the task changes stage, which evidence relationships are established, which are absent, and which are simply not applicable?</strong></p><p>The two views of the same QA task show that it can:</p><ul><li>no REPORT during <code>active</code> → correctly not applicable;</li><li>REPORT and REVIEW present in <code>review</code> → linked;</li><li>no PM-path EVAL on this QA task → correctly not applicable;</li><li>evidence association remains separate from delivery and acceptance.</li></ul><blockquote><p><strong>An evidence diagnostic is not a static status label. It continuously answers which relationships can be proven from the formal facts that exist now.</strong></p></blockquote><p>That is the engineering capability the original research finding became.</p><hr><h2 id="sources-and-evidence-boundary" tabindex="-1">Sources and evidence boundary <a class="header-anchor" href="#sources-and-evidence-boundary" aria-label="Permalink to &quot;Sources and evidence boundary&quot;">​</a></h2><ul><li><a href="https://github.com/crewAIInc/crewAI/pull/7115" target="_blank" rel="noreferrer">CrewAI #7115</a> was merged on August 27, 2026. This article uses it only as an independent public engineering reference for keeping creation attempts distinct from confirmed creations. The PR’s 76,015-event / zero-UUID observation is source-reported and was not independently reproduced here.</li><li><a href="https://github.com/crewAIInc/crewAI/pull/7118" target="_blank" rel="noreferrer">CrewAI #7118</a> remains open at the time of this review. It is cited only as directional public material about a separate terminal record, not as a merged or shipped CrewAI capability.</li><li>CrewAI and CodeFlowMu are not presented here as one implementation lineage. CrewAI does not prove R2 correct, and R2 is not used to judge CrewAI product quality.</li><li>The historical <code>4 / 4 / 2</code> result comes from one fixed ten-report deidentified slice. It is not a defect rate or system-wide quality measure.</li><li><code>TASK-20260827-024</code> is used only as a development-stage calibration case for evidence semantics and formal anchors; this article does not present normal development work as a released-product failure.</li><li><code>TASK-20260827-030-PM-to-QA</code> is a first-party V2.0.4 same-task <code>active → review</code> observation used to demonstrate stage- and role-aware dynamic diagnosis.</li><li>Claims remain scoped to the disclosed tasks, visible edges, and published artifacts rather than all tasks or all desktop/PWA paths.</li></ul>',112))])}const y=n(d,[["render",p]]);export{w as __pageData,y as default};
